import{_ as a,C as o,c as n,o as s,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Partner ledger","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/partner-ledger.md","filePath":"master/finance/reporting/partner-ledger.md","lastUpdated":1792041590000}'),l={name:"master/finance/reporting/partner-ledger.md"};function d(h,e,p,c,g,u){const r=o("ImagePopup");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="partner-ledger" tabindex="-1">Partner ledger <a class="header-anchor" href="#partner-ledger" aria-label="Permalink to &quot;Partner ledger&quot;">​</a></h1><p>The partner ledger shows, for each customer and vendor, what they owe you or what you owe them. Use it to prepare a statement for one partner, or to check a balance before you call them.</p><blockquote><p><strong>In simple words:</strong> It is the general ledger sorted by person instead of by account.</p></blockquote><p>It is in the Accounting app only: <code>Accounting → Reporting → Partner Ledger</code>.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2>',5)),i(r,{src:"/images1/finance/partner_ledger.png",alt:"Partner Ledger with Date Range Last Quarter (01/07/2026 - 30/09/2026), Azure Interiors expanded to show its invoice line"}),e[1]||(e[1]=t('<ul><li><strong><em>Date Range:</em></strong> The period of the entries.</li><li><strong><em>Partners:</em></strong> Pick one or more partners. Leave it empty to list all.</li><li><strong><em>Journals:</em></strong> Limit the report to chosen journals.</li></ul><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><p>The columns are <strong>Partner</strong>, <strong>Journal</strong>, <strong>Account</strong>, <strong>Invoice Date</strong>, <strong>Due Date</strong>, <strong>Debit</strong>, <strong>Credit</strong> and <strong>Balance</strong>.</p><ul><li>Each row is one partner. Click it, or use <strong>Expand All</strong>, to open its lines. <strong>Collapse All</strong> closes them.</li><li>A line shows the journal, the account, the invoice date and the due date.</li><li><strong>Debit</strong> is what the partner owes you. <strong>Credit</strong> is what you owe them or what they paid.</li><li><strong>Balance</strong> is the net amount. A positive balance means the partner owes you.</li><li><strong>Total Partner Ledger</strong> sums the debit and credit at the bottom.</li></ul><p>Example. The report from the sample data lists three partners:</p><table tabindex="0"><thead><tr><th>Partner</th><th>Balance</th><th>Meaning</th></tr></thead><tbody><tr><td>Azure Interiors</td><td>1,207.50</td><td>Invoice INV/2026/1 is unpaid.</td></tr><tr><td>Deco Addict</td><td>0.00</td><td>Invoice INV/2026/2 was fully paid.</td></tr><tr><td>FreshFoods Wholesale</td><td>0.00</td><td>Bill BILL/2026/4 was fully paid.</td></tr></tbody></table><p>For July 2026, Deco Addict has a debit of 891.25 (the invoice) and a credit of 891.25 (the payment). Azure Interiors has a debit of 1,207.50 and no credit.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Click <strong>Export Excel</strong> or <strong>Export PDF</strong> to download the report.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Why is a partner at zero?</strong> All their invoices are paid. The lines cancel each other.</p><p><strong>Why does the partner not appear?</strong> The partner has no posted entry up to the end date.</p><p><strong>How do I see only overdue partners?</strong> Use <a href="./aged-receivable-and-payable.html">Aged receivable and aged payable</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./aged-receivable-and-payable.html">Aged receivable and aged payable</a></li><li><a href="./../../sales/sales/quotations-orders/manage-customers.html">Customers</a></li><li><a href="./">Reporting overview</a></li></ul>',15))])}const f=a(l,[["render",d]]);export{b as __pageData,f as default};
